/** The Basic Program (hold RECORD, press PRESET): one sawtooth oscillator, open filter, Rev 3. */
function basicProgram() {
  const v = new Array(RAW_LENGTH).fill(0);
  Object.assign(v, {
    [P.A_FREQ]: 48, [P.B_FREQ]: 48, [P.A_SAW]: 1, [P.A_PW]: 64, [P.B_PW]: 64, [P.B_KBD]: 1, [P.MIX_A]: 127,
    [P.CUTOFF]: 127, [P.LFO_FREQ]: 92, [P.LFO_TRI]: 1, [P.F_S]: 127, [P.A_S]: 127, [P.REL]: 1,
    [P.UNI_V]: 4, [P.PBR]: 1,
  });
  for (let i = 0; i < 10; i += 1) v[P.CHORD0 + i] = 127;
  return { name: 'Basic Program', values: v, extras: { ...DEFAULT_EXTRAS } };
}

